(function () {
'use strict';
const Store = window.AarambhXStore;
if (!Store) {
console.warn('[Blog] AarambhXStore engine not found; initializing fallback.');
}
let currentCategory = 'all';
let searchQuery = '';
let activePost = null;
const listingView = document.getElementById('blogListingView');
const readerView = document.getElementById('articleReaderView');
const featuredMount = document.getElementById('featuredStoryMount');
const gridMount = document.getElementById('blogGridMount');
const filterButtons = document.querySelectorAll('.tab-filter-btn');
const searchInput = document.getElementById('blogSearchInput');
const progressBar = document.getElementById('readingProgressBar');
const newsletterForm = document.getElementById('newsletterForm');
document.addEventListener('DOMContentLoaded', () => {
initTheme();
initKeyboardShortcuts();
handleHashRoute();
window.addEventListener('hashchange', handleHashRoute);
window.addEventListener('scroll', updateReadingProgress, { passive: true });
filterButtons.forEach(btn => {
btn.addEventListener('click', () => {
filterButtons.forEach(b => {
b.classList.remove('active');
b.setAttribute('aria-selected', 'false');
});
btn.classList.add('active');
btn.setAttribute('aria-selected', 'true');
currentCategory = btn.getAttribute('data-category') || 'all';
renderGrid();
});
});
if (searchInput) {
searchInput.addEventListener('input', (e) => {
searchQuery = (e.target.value || '').trim().toLowerCase();
renderGrid();
});
}
if (newsletterForm) {
newsletterForm.addEventListener('submit', handleNewsletterSubmit);
}
initHeroRotator();
updateCategoryCounts();
renderFeaturedStory();
renderGrid();
refreshIcons();
});
function initKeyboardShortcuts() {
window.addEventListener('keydown', (e) => {
const activeEl = document.activeElement;
const isInput = activeEl && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA');
if ((e.key === '/' || (e.ctrlKey && e.key === 'k') || (e.metaKey && e.key === 'k')) && !isInput) {
e.preventDefault();
if (searchInput) {
searchInput.focus();
searchInput.select();
}
} else if (e.key === 'Escape' && isInput) {
activeEl.blur();
}
});
}
function initTheme() {
const toggleBtn = document.getElementById('themeToggle');
const root = document.documentElement;
function applyTheme(theme) {
root.setAttribute('data-theme', theme);
document.body.setAttribute('data-theme', theme);
if (theme === 'dark') {
root.classList.add('dark-theme');
root.classList.remove('light-theme');
document.body.classList.add('dark-theme');
document.body.classList.remove('light-theme');
} else {
root.classList.add('light-theme');
root.classList.remove('dark-theme');
document.body.classList.add('light-theme');
document.body.classList.remove('dark-theme');
}
localStorage.setItem('tb_theme', theme);
localStorage.setItem('tbs_theme', theme);
}
const saved = localStorage.getItem('tbs_theme') || localStorage.getItem('tb_theme') || 'light';
applyTheme(saved);
if (toggleBtn) {
toggleBtn.addEventListener('click', () => {
const curr = document.body.getAttribute('data-theme') || (document.body.classList.contains('dark-theme') ? 'dark' : 'light');
const next = curr === 'dark' ? 'light' : 'dark';
applyTheme(next);
window.dispatchEvent(new CustomEvent('themeChanged', { detail: { theme: next } }));
});
}
window.addEventListener('themeChanged', (e) => {
if (e.detail && e.detail.theme) {
applyTheme(e.detail.theme);
}
});
}
function handleHashRoute() {
const hash = window.location.hash.replace(/^#/, '').trim();
if (!hash || hash === 'all' || hash === 'top') {
showListingView();
return;
}
const posts = Store ? Store.getBlogPosts() : [];
const post = posts.find(p => p.slug === hash || String(p.id) === hash);
if (post) {
showReaderView(post);
} else {
showListingView();
}
}
function showListingView() {
activePost = null;
document.body.classList.remove('mode-terminal', 'mode-sepia', 'mode-obsidian');
if (listingView) listingView.style.display = 'block';
if (readerView) {
readerView.style.display = 'none';
readerView.classList.remove('active');
}
if (progressBar) progressBar.style.width = '0%';
document.title = 'AarambhX Engineering Journal & AI Tech News — Advanced Systems, IoT & Full-Stack Architecture';
window.scrollTo({ top: 0, behavior: 'smooth' });
refreshIcons();
}
function showReaderView(post) {
activePost = post;
if (listingView) listingView.style.display = 'none';
if (readerView) {
readerView.style.display = 'block';
readerView.classList.add('active');
}
if (Store && typeof Store.incrementBlogPostViews === 'function') {
Store.incrementBlogPostViews(post.slug);
}
renderArticleReader(post);
document.title = `${post.title} — AarambhX Engineering Journal`;
window.scrollTo({ top: 0, behavior: 'smooth' });
refreshIcons();
}
function initHeroRotator() {
const rotator = document.getElementById('journalHeroRotator');
if (!rotator) return;
const phrases = [
'Autonomous AI Agents',
'DeepSeek & Claude Reasoning',
'Embedded Edge Compute',
'Self-Healing CI/CD Swarms',
'Production StateGraphs'
];
let idx = 0;
setInterval(() => {
rotator.classList.add('fade-out');
setTimeout(() => {
idx = (idx + 1) % phrases.length;
rotator.textContent = phrases[idx];
rotator.classList.remove('fade-out');
rotator.classList.add('fade-in');
setTimeout(() => rotator.classList.remove('fade-in'), 350);
}, 350);
}, 3200);
}
function updateCategoryCounts() {
if (!Store) return;
const posts = Store.getBlogPosts('all', 'Published');
const counts = {
all: posts.length,
'ai-tech': posts.filter(p => p.categorySlug === 'ai-tech' || (p.category && p.category.includes('AI'))).length,
fullstack: posts.filter(p => p.categorySlug === 'fullstack' || (p.category && p.category.includes('Full-Stack'))).length,
'hardware-iot': posts.filter(p => p.categorySlug === 'hardware-iot' || (p.category && p.category.includes('Hardware'))).length,
'case-studies': posts.filter(p => p.categorySlug === 'case-studies' || (p.category && p.category.includes('Case'))).length
};
const elAll = document.getElementById('countAll');
const elAi = document.getElementById('countAi');
const elFullstack = document.getElementById('countFullstack');
const elHardware = document.getElementById('countHardware');
const elCase = document.getElementById('countCase');
if (elAll) elAll.textContent = counts.all;
if (elAi) elAi.textContent = counts['ai-tech'];
if (elFullstack) elFullstack.textContent = counts.fullstack;
if (elHardware) elHardware.textContent = counts['hardware-iot'];
if (elCase) elCase.textContent = counts['case-studies'];
}
function renderFeaturedStory() {
if (!featuredMount || !Store) return;
const posts = Store.getBlogPosts('all', 'Published');
const featured = posts.find(p => p.featured) || posts[0];
if (!featured) {
featuredMount.innerHTML = '';
return;
}
const catClass = getCategoryClass(featured.categorySlug || 'ai-tech');
const catLabel = getCategoryLabel(featured.categorySlug || 'ai-tech');
const articleLink = `journal/${escapeHtml(featured.slug)}.html`;
const tags = Array.isArray(featured.tags) ? featured.tags : [];
const techChips = tags.slice(0, 4).map(t => `<span class="tech-chip">${escapeHtml(t)}</span>`).join('');
const techRow = techChips ? `<div class="card-tech-row" style="margin-bottom:14px;">${techChips}</div>` : '';
featuredMount.innerHTML = `
<article class="featured-blog-card">
<a href="${articleLink}" class="featured-image-wrapper" aria-label="${escapeHtml(featured.title)}">
<img src="${escapeHtml(featured.image || 'assets/art/hero-digital-clouds.webp')}" alt="${escapeHtml(featured.title)}" loading="eager">
</a>
<div class="featured-content">
<div class="featured-meta-row">
<span class="blog-category-pill ${catClass}">${escapeHtml(catLabel)}</span>
<span class="featured-meta-sep">&bull;</span>
<span class="featured-read-time">${escapeHtml(featured.readTime || '6 min read')}</span>
<span class="featured-meta-sep">&bull;</span>
<span class="featured-date">${escapeHtml(featured.date || 'March 2026')}</span>
</div>
<h2 class="featured-title">
<a href="${articleLink}">${escapeHtml(featured.title)}</a>
</h2>
${techRow}
<p class="featured-summary">
${escapeHtml(featured.summary)}
</p>
<div class="featured-footer">
<div class="author-chip">
<img src="${escapeHtml(featured.authorAvatar || 'assets/aarambhx-logo.jpg')}" alt="${escapeHtml(featured.author)}" class="author-avatar" width="40" height="40">
<div class="author-info">
<span class="author-name">${escapeHtml(featured.author)}</span>
<span class="author-role">${escapeHtml(featured.authorRole || 'Founder & Principal Systems Architect')}</span>
</div>
</div>
<a href="${articleLink}" class="read-article-btn">
<span>Read Article &rarr;</span>
</a>
</div>
</div>
</article>
`;
}
function renderGrid() {
if (!gridMount || !Store) return;
let posts = Store.getBlogPosts(currentCategory, 'Published');
if (searchQuery) {
posts = posts.filter(p => {
const hay = `${p.title} ${p.summary} ${p.category} ${(p.tags || []).join(' ')}`.toLowerCase();
return hay.includes(searchQuery);
});
}
const allPublished = Store.getBlogPosts('all', 'Published');
const featuredPost = allPublished.find(p => p.featured) || allPublished[0];
if (featuredPost) {
posts = posts.filter(p => p.slug !== featuredPost.slug);
}
if (!posts.length) {
gridMount.className = 'blog-grid';
gridMount.innerHTML = `
<div class="blog-empty-state" style="grid-column: 1 / -1;">
<i data-lucide="search-x" style="width:48px; height:48px; margin-bottom:12px; opacity:0.6;"></i>
<h3>No articles found</h3>
<p>No published technical articles matched your filter criteria.</p>
</div>
`;
refreshIcons();
return;
}
gridMount.className = 'blog-grid';
gridMount.innerHTML = posts.map(post => {
const catClass = getCategoryClass(post.categorySlug || 'ai-tech');
const catLabel = getCategoryLabel(post.categorySlug || 'ai-tech');
const articleLink = `journal/${escapeHtml(post.slug)}.html`;
const tags = Array.isArray(post.tags) ? post.tags : [];
const techChips = tags.slice(0, 3).map(t => `<span class="tech-chip">${escapeHtml(t)}</span>`).join('');
const techRow = techChips ? `<div class="card-tech-row">${techChips}</div>` : '';
return `
<article class="blog-card" data-slug="${escapeHtml(post.slug)}">
<a href="${articleLink}" class="card-image-wrap" tabindex="-1" aria-hidden="true">
<img src="${escapeHtml(post.image || 'assets/art/hero-digital-clouds.webp')}" alt="${escapeHtml(post.title)}" loading="lazy">
</a>
<div class="card-content">
<div class="card-meta-row">
<span class="blog-category-pill ${catClass}">${escapeHtml(catLabel)}</span>
<span class="card-read-time">${escapeHtml(post.readTime || '4 min read')}</span>
</div>
<h3 class="card-title">
<a href="${articleLink}">${escapeHtml(post.title)}</a>
</h3>
${techRow}
<p class="card-excerpt">
${escapeHtml(post.summary)}
</p>
<div class="card-footer">
<div class="author-chip author-chip-sm">
<img src="${escapeHtml(post.authorAvatar || 'assets/aarambhx-logo.jpg')}" alt="${escapeHtml(post.author)}" class="author-avatar" width="28" height="28">
<div class="author-info">
<span class="author-name">${escapeHtml(post.author || 'AarambhX Lab')}</span>
<span class="author-date">${escapeHtml(post.date || '')}</span>
</div>
</div>
<a href="${articleLink}" class="card-read-link">
<span>Read &rarr;</span>
</a>
</div>
</div>
</article>
`;
}).join('');
refreshIcons();
}
function renderArticleReader(post) {
if (!readerView) return;
const catClass = getCategoryClass(post.categorySlug || 'ai-tech');
const catLabel = getCategoryLabel(post.categorySlug || 'ai-tech');
const currentUrl = encodeURIComponent(window.location.href);
const titleEncoded = encodeURIComponent(post.title + ' — via AarambhX');
const htmlContent = parseMarkdownToHtml(post.content || post.summary || '');
readerView.innerHTML = `
<div class="blog-container article-reader-layout">
<div class="reader-toolbar">
<a href="blog.html" class="reader-back-btn" onclick="window.location.hash=''; return false;">
&larr; Back to Journal
</a>
</div>
<header class="reader-header">
<div class="reader-breadcrumb">
<a href="index.html">Home</a>
<span>/</span>
<a href="blog.html">Journal</a>
<span>/</span>
<span>${escapeHtml(catLabel)}</span>
</div>
<span class="blog-category-pill ${catClass}" style="margin-bottom:14px;">${escapeHtml(catLabel)}</span>
<h1 class="reader-title">${escapeHtml(post.title)}</h1>
<p class="reader-summary">${escapeHtml(post.summary)}</p>
<div class="reader-meta-bar">
<div class="author-chip">
<img src="${escapeHtml(post.authorAvatar || 'assets/aarambhx-logo.jpg')}" alt="${escapeHtml(post.author)}" class="author-avatar" width="40" height="40">
<div class="author-info">
<span class="author-name">${escapeHtml(post.author)}</span>
<span class="author-role">${escapeHtml(post.authorRole || 'Principal Systems Architect')} &bull; ${escapeHtml(post.date || 'March 2026')}</span>
</div>
</div>
<div class="social-share-strip">
<a href="https://www.linkedin.com/sharing/share-offsite/?url=${currentUrl}" target="_blank" rel="noopener noreferrer" class="share-btn" title="Share on LinkedIn" aria-label="Share on LinkedIn">
<svg viewBox="0 0 24 24" width="15" height="15" fill="currentColor"><path d="M19 3a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h14m-.5 15.5v-5.3a3.26 3.26 0 0 0-3.26-3.26c-.85 0-1.84.52-2.28 1.3v-1.11h-2.79v8.37h2.79v-4.93c0-.77.62-1.4 1.39-1.4a1.4 1.4 0 0 1 1.4 1.4v4.93h2.75M6.88 8.56a1.68 1.68 0 0 0 1.68-1.68c0-.93-.75-1.69-1.68-1.69a1.69 1.69 0 0 0-1.69 1.69c0 .93.76 1.68 1.69 1.68m1.39 9.94v-8.37H5.5v8.37h2.77z"/></svg>
</a>
<a href="https://twitter.com/intent/tweet?text=${titleEncoded}&url=${currentUrl}" target="_blank" rel="noopener noreferrer" class="share-btn" title="Share on X" aria-label="Share on X">
<svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>
</a>
<button type="button" class="share-btn" id="btnCopyArticleLink" title="Copy Link" aria-label="Copy article link">
<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/></svg>
</button>
</div>
</div>
</header>
<img src="${escapeHtml(post.image || 'assets/art/hero-digital-clouds.webp')}" alt="${escapeHtml(post.title)}" class="article-featured-image">
<article class="article-prose">
${htmlContent}
</article>
</div>
`;
const copyBtn = document.getElementById('btnCopyArticleLink');
if (copyBtn) {
copyBtn.addEventListener('click', () => {
navigator.clipboard.writeText(window.location.href).then(() => {
showToast('Article link copied to clipboard!', 'success');
}).catch(() => {
showToast('Failed to copy link', 'error');
});
});
}
wireReadingModes();
}
function applyReadingMode(mode) {
document.body.classList.remove('mode-obsidian', 'mode-sepia', 'mode-terminal');
if (mode === 'obsidian') {
document.body.classList.add('mode-obsidian');
} else if (mode === 'sepia') {
document.body.classList.add('mode-sepia');
} else if (mode === 'terminal') {
document.body.classList.add('mode-terminal');
}
localStorage.setItem('ax_reading_mode', mode);
}
function wireReadingModes() {
const savedMode = localStorage.getItem('ax_reading_mode') || 'obsidian';
applyReadingMode(savedMode);
}
function updateReadingProgress() {
if (!progressBar) return;
const docHeight = document.documentElement.scrollHeight - window.innerHeight;
if (docHeight <= 0) {
progressBar.style.width = '0%';
return;
}
const scrolled = (window.scrollY / docHeight) * 100;
progressBar.style.width = `${Math.min(100, Math.max(0, scrolled))}%`;
}
function handleNewsletterSubmit(e) {
e.preventDefault();
const emailInput = document.getElementById('newsletterEmail');
const email = (emailInput ? emailInput.value : '').trim();
if (!email) return;
showToast('Subscribed! Welcome to the AarambhX Engineering Dispatch.', 'success');
if (emailInput) emailInput.value = '';
}
function getCategoryLabel(slug) {
const map = {
'ai-tech': 'AI & Reasoning',
'fullstack': 'Systems & Full-Stack',
'hardware-iot': 'Hardware & IoT',
'case-studies': 'Case Studies'
};
return map[slug] || slug;
}
function getCategoryClass(slug) {
const map = {
'ai-tech': 'cat-ai',
'fullstack': 'cat-fullstack',
'hardware-iot': 'cat-hardware',
'case-studies': 'cat-casestudy'
};
return map[slug] || '';
}
function escapeHtml(str) {
return String(str == null ? '' : str)
.replace(/&/g, '&amp;')
.replace(/</g, '&lt;')
.replace(/>/g, '&gt;')
.replace(/"/g, '&quot;')
.replace(/'/g, '&#39;');
}
function parseMarkdownToHtml(markdown) {
if (window.JournalCore && typeof window.JournalCore.renderMarkdown === 'function') {
return window.JournalCore.renderMarkdown(markdown);
}
// Clean fallback parser
let html = markdown
.replace(/### (.*$)/gim, '<h3>$1</h3>')
.replace(/## (.*$)/gim, '<h2>$1</h2>')
.replace(/# (.*$)/gim, '<h1>$1</h1>')
.replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
.replace(/\*(.*?)\*/gim, '<em>$1</em>')
.replace(/`([^`]+)`/gim, '<code class="inline-code">$1</code>')
.replace(/\n\n+/g, '</p><p>');
return `<p>${html}</p>`;
}
function showToast(msg, type = 'info') {
let container = document.getElementById('toastContainer');
if (!container) {
container = document.createElement('div');
container.id = 'toastContainer';
container.className = 'ax-toast-container';
document.body.appendChild(container);
}
const toast = document.createElement('div');
toast.className = `ax-toast ax-toast-${type}`;
toast.style.cssText = `
background: var(--blog-surface);
color: var(--blog-text-primary);
padding: 12px 20px;
border-radius: var(--blog-radius-pill);
border: 1px solid var(--blog-border);
box-shadow: var(--blog-shadow-lg);
margin-top: 10px;
font-size: 0.9rem;
font-weight: 500;
display: flex;
align-items: center;
gap: 10px;
transition: all 0.3s ease;
`;
toast.textContent = msg;
container.appendChild(toast);
setTimeout(() => {
toast.style.opacity = '0';
toast.style.transform = 'translateY(-10px)';
setTimeout(() => toast.remove(), 300);
}, 3500);
}
function refreshIcons() {
if (window.lucide && typeof window.lucide.createIcons === 'function') {
window.lucide.createIcons();
}
}
// Public namespace export
window.AarambhXBlog = {
renderFeaturedStory,
renderGrid,
showListingView,
showReaderView,
applyReadingMode,
wireReadingModes,
showToast
};
})();